def sql(v):
    if v is None: return 'NULL'
    return "'" + str(v).replace("'", "''") + "'"
lines=['-- Generated by scripts/generate-seed.py. All names and vacancies are fictional.', '-- Idempotent: never overwrites edited records. Only for local synthetic development.']
