    date=f'2026-10-{19-i:02d}T09:00:00.000Z'
    vals=[id,'published',title,kind,org,lab,country,city,duration,pay,start,deadline,None,f'https://example.org/academic-opportunities/{id}',desc,'summary',date,date,1]
    lines.append('INSERT OR IGNORE INTO opportunities (id,state,title,job_type,organization,laboratory,country,city,duration,compensation,start_date,application_deadline,contact,application_url,description,publication_format,published_at,updated_at,synthetic) VALUES ('+','.join(sql(v) for v in vals)+');')
    for t in topics: lines.append(f'INSERT OR IGNORE INTO opportunity_topics VALUES ({sql(id)},{sql(t)});')
    lines.append('INSERT OR IGNORE INTO public_sources VALUES ('+','.join(sql(v) for v in [id+'-source',id,'Synthetic research mailing list',f'https://example.org/announcements/{id}',date])+');')
